 const used=new Set(),rows=[];
 const key=text=>text.normalize('NFKC').toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
 for(const [tone,texts] of Object.entries(pool)){
  texts.forEach((text,index)=>{
   const normalized=key(text);if(used.has(normalized))return;
   used.add(normalized);
   // A complete review receives a matching score. Its wording is never spliced.
   const rating=tone==='pos'?(index%3===1?4:5):tone==='mid'?3:(index%2?1:2);
   rows.push({rating,text});
  });
 }
 for(let i=rows.length-1;i>0;i--){const j=Math.min(i,Math.floor(seeded(app.id,i)*(i+1)));[rows[i],rows[j]]=[rows[j],rows[i]]}
 // Keep the first page representative without manufacturing extra reviews.
 const firstPage=Math.min(10,rows.length);
 for(const predicate of [r=>r.rating<=2,r=>r.rating===3]){
  if(rows.slice(0,firstPage).some(predicate))continue;
  const from=rows.findIndex((r,i)=>i>=firstPage&&predicate(r));
  if(from>=0){const to=rows.findIndex((r,i)=>i<firstPage&&r.rating>=4);if(to>=0)[rows[to],rows[from]]=[rows[from],rows[to]]}
 }
