function transitionPages(nextName,direction='forward'){
 if(state.busy||nextName===state.page)return Promise.resolve();
 state.busy=true;
 const old=$(`[data-page="${state.page}"]`),next=$(`[data-page="${nextName}"]`);
 state.scroll[state.page]=old?.scrollTop||0;
 if(old){old.getAnimations().forEach(a=>a.cancel());old.classList.remove('active','page-arrive-forward','page-arrive-back')}
 next.getAnimations().forEach(a=>a.cancel());
 next.classList.add('active',direction==='back'?'page-arrive-back':'page-arrive-forward');
 if(nextName==='detail')next.scrollTop=0;else next.scrollTop=state.scroll[nextName]||0;
 $('#scrollTopBtn').classList.toggle('shown',next.scrollTop>500);
 if(nextName==='catalog')updateChipScrollState();
 const duration=250;
 return new Promise(resolve=>setTimeout(()=>{next.classList.remove('page-arrive-forward','page-arrive-back');state.page=nextName;state.busy=false;updateNav();resolve()},duration));
}
