let installViewSwitchToken=0;
let sheetPanelTransitionToken=0;
function resetSheetPanelTransition(panel){
 if(!panel)return;
 panel.getAnimations().forEach(animation=>animation.cancel());
 panel.classList.remove('sheet-panel-transition');
 ['position','top','left','width','zIndex','pointerEvents','opacity','transform'].forEach(key=>panel.style[key]='');
}
function resetSheetPanelState(){
 sheetPanelTransitionToken++;
 const sheet=$('#installSheet');
 sheet.getAnimations().forEach(animation=>animation.cancel());
 [$('#installSheetLoading'),$('#installAccountLoading'),$('#installAccountResult'),$('#installSheetBody')].forEach(resetSheetPanelTransition);
 sheet.style.height='';sheet.style.overflowY='';
}
async function transitionSheetPanel(from,to){
 if(!from||!to||from===to||from.hidden){if(to)to.hidden=false;return}
 const sheet=$('#installSheet');
 const token=++sheetPanelTransitionToken;
 [from,to].forEach(resetSheetPanelTransition);
 const startHeight=sheet.getBoundingClientRect().height;
 const fromTop=from.offsetTop,fromLeft=from.offsetLeft,fromWidth=from.offsetWidth;
 sheet.style.height=`${startHeight}px`;
 sheet.style.overflowY='hidden';
 from.hidden=true;to.hidden=false;
 sheet.style.height='auto';
 const endHeight=sheet.getBoundingClientRect().height;
 sheet.style.height=`${startHeight}px`;
 from.hidden=false;
 Object.assign(from.style,{position:'absolute',top:`${fromTop}px`,left:`${fromLeft}px`,width:`${fromWidth}px`,zIndex:'2',pointerEvents:'none'});
 Object.assign(to.style,{zIndex:'1',pointerEvents:'none'});
 from.classList.add('sheet-panel-transition');to.classList.add('sheet-panel-transition');
 void sheet.offsetHeight;
 const easing='cubic-bezier(.22,.78,.2,1)';
 const fromAnimation=from.animate([
  {opacity:1,transform:'translateY(0)'},
  {opacity:0,transform:'translateY(-5px)'}
 ],{duration:180,easing:'ease-out',fill:'both'});
 const toAnimation=to.animate([
  {opacity:0,transform:'translateY(10px)'},
  {opacity:1,transform:'translateY(0)'}
 ],{duration:280,delay:80,easing,fill:'both'});
 const heightAnimation=sheet.animate([
  {height:`${startHeight}px`},
  {height:`${endHeight}px`}
 ],{duration:380,easing,fill:'both'});
 try{await Promise.all([fromAnimation.finished,toAnimation.finished,heightAnimation.finished])}catch(_){return}
 if(token!==sheetPanelTransitionToken)return;
 from.hidden=true;
 fromAnimation.cancel();toAnimation.cancel();heightAnimation.cancel();
 [from,to].forEach(resetSheetPanelTransition);
 sheet.style.height='';sheet.style.overflowY='';
 to.hidden=false;sheet.scrollTop=0;
}
async function switchInstallView(target,animate=true){
 const main=$('#installMainView'),guide=$('#installGuideView');
 const to=target==='guide'?guide:main,from=target==='guide'?main:guide;
 const direction=target==='guide'?1:-1;
 const sheet=$('#installSheet'),body=$('#installSheetBody');
 const resetView=el=>{
  el.getAnimations().forEach(a=>a.cancel());
  el.classList.remove('install-view-switching','install-view-out-forward','install-view-out-back','install-view-in-forward','install-view-in-back');
  ['opacity','transform','position','top','left','right','width','zIndex','pointerEvents','visibility'].forEach(k=>el.style[k]='');
 };
 const resetSheet=()=>{
  sheet.getAnimations().forEach(a=>a.cancel());
  sheet.style.height='';
  sheet.style.overflowY='';
  body.style.position='';
 };
 if(!animate){
  installViewSwitchToken++;
  [main,guide].forEach(resetView);resetSheet();
  main.hidden=target!=='main';guide.hidden=target!=='guide';
  sheet.scrollTop=0;return;
 }
 if(from.hidden||!to.hidden)return;
 const token=++installViewSwitchToken;
 [main,guide].forEach(resetView);resetSheet();

 // Freeze the exact current sheet size before changing which view participates in layout.
 const oldScroll=sheet.scrollTop;
 const startHeight=sheet.getBoundingClientRect().height;
 sheet.style.height=`${startHeight}px`;
 sheet.style.overflowY='hidden';
 body.style.position='relative';

 // Measure the target view in normal flow. This all happens in one JS frame, so there is no visible hard swap.
 from.hidden=true;
 to.hidden=false;
 sheet.style.height='auto';
 const endHeight=sheet.getBoundingClientRect().height;
 sheet.style.height=`${startHeight}px`;

 // Put the old view back as an overlay while the new view remains in normal flow underneath it.
 const stageTop=to.offsetTop;
 from.hidden=false;
 Object.assign(from.style,{
  position:'absolute',top:`${stageTop-oldScroll}px`,left:'0',right:'0',width:'100%',zIndex:'2',pointerEvents:'none'
 });
 Object.assign(to.style,{opacity:'0',zIndex:'1',pointerEvents:'none'});
 sheet.scrollTop=0;

 // Force the frozen start state to be committed before the animations begin.
 void sheet.offsetHeight;
 if(token!==installViewSwitchToken)return;

 // Fast, clean fade: no sliding/scaling so text never looks smeared between views.
 const easing='cubic-bezier(.2,.7,.2,1)';
 const duration=160;
 const fromAnim=from.animate([
  {opacity:1},
  {opacity:0}
 ],{duration:75,easing:'ease-out',fill:'both'});
 const toAnim=to.animate([
  {opacity:0},
  {opacity:1}
 ],{duration:95,delay:55,easing:'ease-out',fill:'both'});
 const heightAnim=sheet.animate([
  {height:`${startHeight}px`},
  {height:`${endHeight}px`}
 ],{duration,easing,fill:'both'});

 try{await Promise.all([fromAnim.finished,toAnim.finished,heightAnim.finished])}catch(_){return}
 if(token!==installViewSwitchToken)return;

 // Commit the target layout only after both the content and sheet height have finished moving.
 from.hidden=true;
 fromAnim.cancel();toAnim.cancel();heightAnim.cancel();
 [main,guide].forEach(resetView);resetSheet();
 to.hidden=false;
 sheet.scrollTop=0;
}
function showInstallMainView(animate=true){switchInstallView('main',animate)}
function showInstallGuideView(){state.installGuideOpened=true;if(!$('#installGateMessage').hidden)updateInstallGateMessage();switchInstallView('guide',true)}
const MINIAPP_MIRROR_ID=new URLSearchParams(location.search).get('mirror')||'';
const MINIAPP_BUSY_RU='В данный момент все аккаунты заняты. Попробуйте позже.';
const MINIAPP_BUSY_EN='All accounts are currently busy. Please try again later.';
function isMiniappBusy(error){return String(error||'').includes(MINIAPP_BUSY_RU)}
function miniappBusyMessage(){return state.lang==='ru'?MINIAPP_BUSY_RU:MINIAPP_BUSY_EN}
function telegramInitData(){return window.Telegram?.WebApp?.initData||''}
function isMirrorDemo(){return Boolean(MINIAPP_MIRROR_ID)}
async function mirrorDemoFetch(path,options={}){
 const headers=new Headers(options.headers||{});headers.set('X-Telegram-Init-Data',telegramInitData());
 if(options.body&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');
 const res=await fetch(path,{...options,headers,cache:'no-store'});
 let data={};try{data=await res.json()}catch(_){data={}}
 if(!res.ok||data.ok===false)throw new Error(data.error||`HTTP ${res.status}`);
 return data;
}
function stopMirrorDemoPolling(){
 if(state.mirrorDemoPollTimer){clearTimeout(state.mirrorDemoPollTimer);state.mirrorDemoPollTimer=null}
}
async function refreshMirrorAccessState(){
 if(!isMirrorDemo())return;
 try{
  const data=await mirrorDemoFetch(`/api/mirror/context?mirror=${encodeURIComponent(MINIAPP_MIRROR_ID)}`);
  state.mirrorAccessBlocked=Boolean(data.userBlocked);
  if(state.mirrorAccessBlocked)showToast(state.lang==='ru'?'Свободных данных нет':'No data available');
 }catch(_){}
}
async function closeMirrorDemoSessionBestEffort(sessionId){
 if(!sessionId||!isMirrorDemo())return;
 try{await mirrorDemoFetch(`/api/mirror/session/${encodeURIComponent(sessionId)}/done?mirror=${encodeURIComponent(MINIAPP_MIRROR_ID)}`,{method:'POST'})}catch(_){}
}
async function pollMirrorDemoSession(){
 stopMirrorDemoPolling();
 const sessionId=state.mirrorDemoSessionId;if(!sessionId||!isMirrorDemo())return;
 try{
  const data=await mirrorDemoFetch(`/api/mirror/session/${encodeURIComponent(sessionId)}?mirror=${encodeURIComponent(MINIAPP_MIRROR_ID)}`);
  if(sessionId!==state.mirrorDemoSessionId)return;
  if(data.status==='PREPARING'){
   if(Number.isFinite(Number(data.queuePosition)))renderPreparationQueue(Number(data.queuePosition));
  }
  if(data.status==='READY'&&!state.mirrorDemoReadyShown){
   renderPreparationQueue(1,true);
   state.mirrorDemoPendingReady=data;
   showMirrorDemoReadyWhenQueueIsFirst();
  }
  if(data.status==='DEVICE_SEEN'){
   stopPreparationQueue();
   const id=state.mirrorDemoSessionId;state.mirrorDemoSessionId=null;stopMirrorDemoPolling();
   closeSheet({skipDemoClose:true});
   showToast(state.lang==='ru'?'Устройство обнаружено — окно закрыто':'Device detected — window closed');
   return;
  }
  if(data.status==='ERROR'){
   stopPreparationQueue();
   state.mirrorDemoSessionId=null;stopMirrorDemoPolling();
   $('#installAccountLoading').hidden=true;$('#installSheetBody').hidden=false;
   showToast(isMiniappBusy(data.error)?miniappBusyMessage():(data.error||(state.lang==='ru'?'Не удалось получить аккаунт':'Could not get account')));
   return;
  }
  if(data.status==='CLOSED'||data.status==='EXPIRED'){
   stopPreparationQueue();
   state.mirrorDemoSessionId=null;stopMirrorDemoPolling();closeSheet({skipDemoClose:true});
   if(data.status==='EXPIRED')showToast(state.lang==='ru'?'Время истекло':'Time expired');
   return;
  }
 }catch(err){
  console.warn('Mirror poll:',err);
  const msg=String(err?.message||'');
  if(/остановлено|неизвестное зеркало|stopped|unknown mirror/i.test(msg)){
   state.mirrorDemoSessionId=null;stopMirrorDemoPolling();closeSheet({skipDemoClose:true});
   showToast(state.lang==='ru'?'Зеркало остановлено':'Mirror is stopped');
   return;
  }
 }
 if(state.mirrorDemoSessionId===sessionId)state.mirrorDemoPollTimer=setTimeout(pollMirrorDemoSession,800);
}
function showMirrorDemoReadyWhenQueueIsFirst(){
 const data=state.mirrorDemoPendingReady;
 const sessionId=state.mirrorDemoSessionId;
 if(!data||!sessionId||state.mirrorDemoReadyShown||state.accountQueuePosition!==1)return;
 state.mirrorDemoReadyShown=true;
 state.mirrorDemoPendingReady=null;
 stopPreparationQueue();
 renderPreparationQueue(1,true);
 setTimeout(()=>{
  if(sessionId!==state.mirrorDemoSessionId)return;
  showAccountResult(data.credentials||ACCOUNT_PLACEHOLDER,data.expiresAt||null);
  showToast(state.lang==='ru'?'Данные аккаунта готовы':'Account data are ready');
 },450);
}
async function beginMirrorDemoRequest(app){
 state.mirrorDemoReadyShown=false;state.mirrorDemoPendingReady=null;stopMirrorDemoPolling();
 const data=await mirrorDemoFetch('/api/mirror/request',{method:'POST',body:JSON.stringify({mirror:MINIAPP_MIRROR_ID,appId:app.id,appName:tx(app.name)})});
 state.mirrorDemoSessionId=data.sessionId;
 await pollMirrorDemoSession();
}
const ACCOUNT_PLACEHOLDER={login:'demo-shared@example.invalid',password:'DEMO-ONLY'};
