function highlightSignInNotice(){
 const el=document.querySelector('.sign-in-notice');if(!el)return;
 try{el.scrollIntoView({behavior:'smooth',block:'center'})}catch(_){try{el.scrollIntoView()}catch(__){}}
 el.classList.remove('attention');
 void el.offsetWidth;
 el.classList.add('attention');
 clearTimeout(state._signInNoticeAttentionTimer);
 state._signInNoticeAttentionTimer=setTimeout(()=>{el.classList.remove('attention')},1900);
}
function stopPreparationQueue(){
 if(state.accountQueueTimer){clearTimeout(state.accountQueueTimer);state.accountQueueTimer=null}
 if(state.accountQueueRevealTimer){clearTimeout(state.accountQueueRevealTimer);state.accountQueueRevealTimer=null}
 const warmup=$('#accountQueueWarmup');if(warmup)warmup.remove();
 state.accountQueueStartedAt=null;
}
function renderPreparationQueue(position,ready=false){
 const pos=Math.max(1,Math.min(9,Number(position)||1));
 state.accountQueuePosition=pos;
 const activeStep=ready?3:pos>=7?0:pos>=5?1:2;
 $$('.account-search-step').forEach((step,index)=>{
  step.classList.toggle('completed',index<activeStep);
  step.classList.toggle('active',index===activeStep);
  if(index===activeStep)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current');
 });
}
function startPreparationQueue(){
 stopPreparationQueue();
 state.accountQueueStartedAt=Date.now();
 state.accountQueuePosition=9;
 renderPreparationQueue(9);
 // В Mini App длительность подготовки по-прежнему задаёт backend.
 if(isMirrorDemo())return null;
 // Для обычного preview сохраняем прежнюю длительность визуального поиска.
 const duration=20000+Math.floor(Math.random()*2001);
 const weights=[.09,.1,.11,.12,.13,.14,.15,.16];
 const delays=weights.map(weight=>Math.round(duration*weight));
 for(let i=delays.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[delays[i],delays[j]]=[delays[j],delays[i]]}
 let index=0;
 const next=()=>{
  if(index>=8){state.accountQueueTimer=null;renderPreparationQueue(1);return}
  state.accountQueueTimer=setTimeout(()=>{
   state.accountQueueTimer=null;index+=1;renderPreparationQueue(9-index);next();
  },delays[index]);
 };
 next();
 return duration;
}
function stopAccountCountdown(){
 if(state.accountCountdownTimer){clearTimeout(state.accountCountdownTimer);state.accountCountdownTimer=null}
}
function startAccountCountdown(seconds=600){
 stopAccountCountdown();
 const end=Date.now()+seconds*1000;
 const draw=()=>{
  const left=Math.max(0,Math.ceil((end-Date.now())/1000));
  const min=Math.floor(left/60),sec=left%60;
  $('#accountCountdown').textContent=`${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
  if(left<=0){state.accountCountdownTimer=null;return}
  state.accountCountdownTimer=setTimeout(draw,250);
 };
 draw();
}
function startAccountCountdownUntil(expiresAt){
 const parsed=Date.parse(expiresAt);
 if(!Number.isFinite(parsed)){startAccountCountdown(600);return}
 // Экран всегда начинает визуальный отсчёт с полных 10:00 в момент показа.
 // Backend-сессия создаётся в тот же момент и имеет тот же 10-минутный срок.
 startAccountCountdown(600);
}
