 icon.src=app.icon;icon.alt=tx(app.name);icon.onerror=()=>{icon.onerror=null;icon.src=fallbackSvg(app)};
 $('#accountResultAppName').textContent=tx(app.name);
 $('#installSheet').classList.add('account-result-mode');
 const visiblePanel=[$('#installSheetLoading'),$('#installAccountLoading'),$('#installSheetBody')].find(panel=>panel&&!panel.hidden);
 if(visiblePanel)transitionSheetPanel(visiblePanel,$('#installAccountResult'));
 else $('#installAccountResult').hidden=false;
