function isTelegramMiniApp(){
 return Boolean(window.Telegram?.WebApp&&(telegramInitData()||MINIAPP_MIRROR_ID));
}
function setupTelegramMiniAppViewport(){
 const tg=window.Telegram?.WebApp;if(!tg)return;
 const ua=navigator.userAgent||'',platform=navigator.platform||'';
 const isIPad=/iPad/.test(ua)||(platform==='MacIntel'&&navigator.maxTouchPoints>1);
 try{
  tg.ready();tg.expand();
  if(isIPad&&typeof tg.requestFullscreen==='function'&&(!tg.isVersionAtLeast||tg.isVersionAtLeast('8.0')))tg.requestFullscreen();
  if(typeof tg.disableVerticalSwipes==='function')tg.disableVerticalSwipes();
 }catch(_){}
 const stopGesture=e=>e.preventDefault();
 document.addEventListener('gesturestart',stopGesture,{passive:false});
 document.addEventListener('gesturechange',stopGesture,{passive:false});
 document.addEventListener('gestureend',stopGesture,{passive:false});
 document.addEventListener('touchmove',e=>{if(e.touches&&e.touches.length>1)e.preventDefault()},{passive:false});
 window.addEventListener('wheel',e=>{if(e.ctrlKey)e.preventDefault()},{passive:false});
}
function setupAppViewport(){
 // Device type never blocks access to the catalog.
 if(isTelegramMiniApp()){
  document.body.classList.remove('preview-mode');
  document.body.classList.add('telegram-miniapp');
  setupTelegramMiniAppViewport();
 }else{
  document.body.classList.remove('telegram-miniapp');
  document.body.classList.add('preview-mode');
 }
}
