 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#videoOverlay').hidden)closeVideoOverlay();else if(!$('#sheetOverlay').hidden)closeSheet();else if(!$('#sideOverlay').hidden)$('#sideOverlay').hidden=true;else if(state.page==='detail')closeDetail()}});
