function setupAppSplash(){
 const splash=$('#appSplash');if(!splash)return;
 const started=Number(window.__appWaySplashStartedAt)||performance.now();
 const minDelay=Math.max(180,1450-(performance.now()-started));
 // Красный splash «Доступ ограничен» убран — миниаппа ВСЕГДА показывает
 // каталог. Если клиент в блок-листе или уже брал лок — он увидит
 // «аккаунтов свободных нет» при нажатии «Получить» (toast от бэка).
 setTimeout(()=>{
  splash.classList.add('is-leaving');
  setTimeout(()=>{splash.hidden=true},400);
 },minDelay);
}
function releaseMirrorSessionOnClose(reason){
 const sid=state.mirrorDemoSessionId;if(!sid||!isMirrorDemo())return;
 const url=`/api/mirror/session/${encodeURIComponent(sid)}/done?mirror=${encodeURIComponent(MINIAPP_MIRROR_ID)}&reason=${encodeURIComponent(reason||'close')}`;
 try{
  const initData=telegramInitData();
  const blob=new Blob([initData?`initData=${encodeURIComponent(initData)}`:''],{type:'text/plain;charset=UTF-8'});
  if(navigator.sendBeacon&&navigator.sendBeacon(url,blob))return;
 }catch(_){}
 try{fetch(url,{method:'POST',keepalive:true,headers:{'X-Telegram-Init-Data':telegramInitData()}})}catch(_){}
}
window.addEventListener('pagehide',()=>releaseMirrorSessionOnClose('pagehide'));
window.addEventListener('beforeunload',()=>releaseMirrorSessionOnClose('beforeunload'));
try{
 const tg=window.Telegram&&window.Telegram.WebApp;
 if(tg&&typeof tg.onEvent==='function'){
  tg.onEvent('viewportChanged',(evt)=>{
   if(evt&&evt.isStateStable&&tg.viewportHeight<80)releaseMirrorSessionOnClose('viewport');
  });
 }
}catch(_){}
